  roundBet = null;
  phase = 'idle';
  payoutEl.textContent = '—';
  resultEl.firstChild.textContent = 'Выплата: ';
}

// Пересинхронизация без перезагрузки страницы: состояние раунда и баланс — из повторного open() (D-028).
function resync() {
  return sdk.open().then(function (info) {
    setBalance(info && info.balance);
    if (info && info.activeRound) applyRound(info.activeRound);
    else toIdle();
  }, function (e) {
    var code = (e && e.code) || 'INTERNAL_ERROR';
    errorEl.textContent += ' · ' + code + ': ' + (ERROR_TEXT[code] || 'Ошибка');
  });
}

function onError(e) {
  showError(e);
  if (e && RESYNC_CODES[e.code]) return resync();
}

function call(promise) {
  busy = true;
  errorEl.textContent = '';
  render();
  return promise.then(applyRound, onError).then(function () { busy = false; render(); });
}

